// Command SeqbenchMcp-cli is a CLI + REPL for the SeqbenchMcp SDK,
// built on the AQL engine. Positional arguments are joined into a
// single AQL expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/aql-lang/aql/eng/go"
	"github.com/aql-lang/aql/eng/go/parser"
	sdk "github.com/voxgig-sdk/seqbench-mcp-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "seqbench-mcp"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "alphafold_lookup aso_design base_editing_design batch batch__workflow characterize_sequence cloning_simulate codon_adaptation_index codon_optimize construct_autofix construct_qc crispr_grna_design crispr_hdr_donor crispr_offtarget_check cross_dimer dna_molarity double_digest export_echo_picklist export_opentrons_protocol export_plate_layout expression_heatmap_cluster fastq_qc_report fastq_trim find_orf format_sequence functional_enrichment gc_content gene_dossier gene_expression gene_model golden_gate_fidelity hgvs_convert id_map_poll id_map_submit in_silico_pcr kasp_primer_design list_tool melting_temperature motif_finder multiple_sequence_alignment oligo_analysi ortholog_map pairwise_alignment parse_genbank parse_sanger_trace plasmid_annotate plasmid_deep_annotate plasmid_full_report plasmid_identify prime_editing_design prime_editing_twin_design primer_design primer_specificity protease_digestion protein_annotate_poll protein_annotate_submit protein_hydrophobicity protein_property random_sequence restriction_site reverse_complement reverse_translate rna_fold sanger_vs_reference save_permalink seqfile_stat sequence_fetch sequence_format_convert sequence_report sequence_search sequencing_readback_verify session_create session_get session_run session_set sirna_design site_directed_mutagenesi translate variant_annotate variant_comparator verify_assembly verify_construct virtual_gel volcano_plot_data web_search"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — AQL-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<AQL expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single AQL expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      SEQBENCH_MCP_APIKEY (api key), SEQBENCH_MCP_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: SEQBENCH_MCP_APIKEY carries the API key and
	// SEQBENCH_MCP_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("SEQBENCH_MCP_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("SEQBENCH_MCP_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewSeqbenchMcpSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
